'use strict';
const path=require('node:path');
const fs=require('node:fs');
const {spawn}=require('node:child_process');
const MAGIC=0x31474c56,MAX_PIXELS=8388608;
// Binary framing keeps pixel messages out of JSON. Only one unacknowledged frame
// per surface is generated by the native host; fragmented pipe reads stay bounded.
function createFrameDecoder(onFrame,onError){
  let header=Buffer.alloc(24),used=0,payload=null,offset=0,info=null,failed=false;
  return chunk=>{
    if(failed)return;
    try{while(chunk.length){
      if(!payload){const size=Math.min(24-used,chunk.length);chunk.copy(header,used,0,size);used+=size;chunk=chunk.subarray(size);if(used<24)continue;
        const id=header.readUInt32LE(4),width=header.readUInt32LE(8),height=header.readUInt32LE(12),sequence=header.readUInt32LE(16),sizeBytes=header.readUInt32LE(20);
        if(header.readUInt32LE(0)!==MAGIC||![1,2].includes(id)||width<4||height<4||width>4096||height>3072||width*height>MAX_PIXELS||sizeBytes!==width*height*4)throw Error('Invalid Liquid Glass frame');
        info={id,width,height,sequence};payload=Buffer.allocUnsafe(sizeBytes);offset=0;
      }
      const size=Math.min(payload.length-offset,chunk.length);chunk.copy(payload,offset,0,size);offset+=size;chunk=chunk.subarray(size);
      if(offset===payload.length){const frame={...info,pixels:payload};payload=null;used=0;onFrame(frame);}
    }}catch(error){failed=true;payload=null;onError(error);}
  };
}
function createLiquidGlass({app,screen,getIsland,getDashboard,getSettings,isExpanded=()=>false,onError=()=>{},spawnImpl=spawn,existsImpl=fs.existsSync}){
  let child=null,timer=null,stopped=false,lastFailure=0,reason=null,frames=0;
  const keys=new Map(),windows=new Map(),waiting=new Map(),active=new Set();
  const helper=()=>app.isPackaged?path.join(process.resourcesPath,'native/liquid-glass/Sonara.LiquidGlass.exe'):path.join(__dirname,'../native/liquid-glass/bin/Sonara.LiquidGlass.exe');
  const send=(win,value)=>{if(win&&!win.isDestroyed()&&!win.webContents.isLoading())win.webContents.send('pulse:liquid-glass',value);};
  function write(command){if(child?.stdin.writable)child.stdin.write(JSON.stringify(command)+'\n');}
  function release(){
    const previous=child;child=null;keys.clear();waiting.clear();active.clear();
    previous?.stdin.end();if(previous){const timeout=setTimeout(()=>{if(previous.exitCode===null)previous.kill();},2000);timeout.unref();previous.once('exit',()=>clearTimeout(timeout));}
  }
  function start(){
    if(child||Date.now()-lastFailure<5000||process.platform!=='win32')return;
    if(!existsImpl(helper())){reason='Liquid Glass helper unavailable';return;}
    const processHandle=spawnImpl(helper(),[String(process.pid)],{windowsHide:true,stdio:['pipe','pipe','pipe']});child=processHandle;
    processHandle.stdout.on('data',createFrameDecoder(frame=>{
      if(child!==processHandle)return;
      const target=windows.get(frame.id),key=keys.get(frame.id);
      if(!target||target.isDestroyed()||!target.isVisible()||!key){write({Op:'ack',Id:frame.id,Sequence:frame.sequence});return;}
      waiting.set(frame.id,frame.sequence);active.add(frame.id);frames++;reason=null;
      send(target,{active:true,backend:'veyra-d3d11',...frame});
    },error=>{reason=error.message;onError(error);release();lastFailure=Date.now();}));
    processHandle.stderr.on('data',bytes=>{reason=bytes.toString().slice(0,300);});
    processHandle.on('error',error=>{reason=error.message;onError(error);});
    processHandle.on('exit',()=>{if(child!==processHandle)return;child=null;keys.clear();waiting.clear();active.clear();lastFailure=Date.now();for(const win of windows.values())send(win,{active:false,reason:reason||'native-host-exited'});});
    processHandle.stdin.on('error',()=>{});
  }
  function sync(){
    if(stopped)return;
    const settings=getSettings();let count=0;
    for(const [id,win,enabled] of [[1,getIsland(),settings.islandEnabled===true&&settings.islandEdge!=='off'],[2,getDashboard(),settings.dashboardGlass===true]]){
      windows.set(id,win);
      const opacity=id===1?settings.islandOpacity:settings.dashboardOpacity;
      const wanted=enabled&&opacity!==0&&win&&!win.isDestroyed()&&win.isVisible()&&!win.isMinimized()&&!win.webContents.isLoading();
      if(!wanted){if(keys.has(id)){write({Op:'remove',Id:id});keys.delete(id);active.delete(id);waiting.delete(id);send(win,{active:false});}continue;}
      count++;start();if(!child)continue;
      const bounds=win.getBounds(),pixels=screen.dipToScreenRect(win,bounds),scale=pixels.width/bounds.width;
      const square=id===2&&(win.isFullScreen?.()||win.isMaximized?.());
      const configuration={Op:'surface',Id:id,X:pixels.x,Y:pixels.y,Width:pixels.width,Height:pixels.height,Scale:scale,Radius:square?0:Math.min(pixels.height/2,(id===1?(isExpanded()?26:22):24)*scale),Static:id===1&&settings.islandEdge==='light'};
      const key=JSON.stringify(configuration);
      if(keys.get(id)!==key){keys.set(id,key);write(configuration);}
      send(win,{opacity:Number.isFinite(opacity)?opacity:.55});
    }
    if(!count&&child)release();
  }
  return {start(){if(stopped||timer)return;sync();timer=setInterval(sync,150);timer.unref();},sync,
    presented(sender,{id,sequence}={}){const win=windows.get(id);if(win&&!win.isDestroyed()&&win.webContents===sender&&waiting.get(id)===sequence){waiting.delete(id);write({Op:'ack',Id:id,Sequence:sequence});}},
    getStatus:()=>({backend:'veyra-d3d11',enabled:Boolean(child),active:[...active],frames,reason,captureExcluded:false,source:'underlying-hwnd-composition'}),
    stop(){stopped=true;clearInterval(timer);timer=null;release();windows.clear();}
  };
}
module.exports={createFrameDecoder,createLiquidGlass};
